/**
 * legal.cjs
 * Step 10.1b-1: the legal pages are made from docs/legal/*.md, with no markdown library.
 * Shared by scripts/build-legal.mjs (writes the generated files), scripts/check-launch.mjs
 * (the launch checklist) and the Jest tests (the generated files are up to date).
 *
 *   renderTexts(root)     → src/legal/texts.generated.ts (the five pages as blocks + LEGAL_VERSION)
 *   renderLicences(root)  → src/legal/licences.generated.ts (open-source packages, from package metadata)
 *   placeholders(root)    → the bracketed details still to fill in
 *   userFacingMentions(root, words) → user-facing strings that name a service (OpenAI, Whisper)
 *
 * Node built-ins only (typescript, a dev dependency, for the string scan).
 */

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

/** The published pages, in the order /legal lists them. `file` is in docs/legal. */
const LEGAL_PAGES = [
  { slug: 'privacy', file: 'privacy-policy.md', title: 'Privacy Policy' },
  { slug: 'terms', file: 'terms-of-service.md', title: 'Terms of Service' },
  { slug: 'refunds', file: 'refund-policy.md', title: 'Refund Policy' },
  { slug: 'cookies', file: 'cookie-policy.md', title: 'Cookie Policy' },
  { slug: 'legal', file: 'legal-notice.md', title: 'Legal Notice' },
];

/** Other legal documents that must be complete before launch (not published). */
const INTERNAL_DOCS = ['data-breach-plan.md'];

const TEXTS_OUT = 'src/legal/texts.generated.ts';
const LICENCES_OUT = 'src/legal/licences.generated.ts';

const HEADER = (what) =>
  `// Generated by scripts/build-legal.mjs from ${what}. Do not edit: run \`npm run build:legal\`.\n` +
  '// A Jest test (src/legal/__tests__) fails when this file is behind its source.\n';

// ── Markdown → blocks ──────────────────────────────────────────────────────

/** Bare links in the texts: web addresses, www.…, emails. */
const AUTOLINK = /(https?:\/\/[^\s)]+[^\s).,;:])|(www\.[a-z0-9-]+(?:\.[a-z0-9-]+)*\.[a-z]{2,})|([A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,})/;

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** "our Privacy Policy" → a link to /privacy (never to the page itself). */
function pageLinker(selfSlug) {
  const others = LEGAL_PAGES.filter((p) => p.slug !== selfSlug);
  const re = new RegExp(`\\b(${others.map((p) => escapeRegExp(p.title)).join('|')})\\b`);
  return { re, hrefOf: (title) => `/${others.find((p) => p.title === title).slug}` };
}

function linkSpans(text, bold, linker) {
  const out = [];
  let rest = text;
  while (rest.length > 0) {
    const auto = AUTOLINK.exec(rest);
    const page = linker.re.exec(rest);
    const m = auto && (!page || auto.index <= page.index) ? auto : page;
    if (!m) break;
    if (m.index > 0) out.push(span(rest.slice(0, m.index), bold));
    const found = m[0];
    let href;
    if (m === page) href = linker.hrefOf(found);
    else if (m[1]) href = found;
    else if (m[2]) href = `https://${found}`;
    else href = `mailto:${found}`;
    out.push(span(found, bold, href));
    rest = rest.slice(m.index + found.length);
  }
  if (rest.length > 0) out.push(span(rest, bold));
  return out;
}

function span(text, bold, href) {
  const s = { text };
  if (bold) s.bold = true;
  if (href) s.href = href;
  return s;
}

/** One line of text: **bold** parts, then links inside each part. */
function parseInline(text, linker) {
  const parts = text.split('**');
  // An unmatched ** stays as written.
  if (parts.length % 2 === 0) parts.splice(-2, 2, `${parts[parts.length - 2]}**${parts[parts.length - 1]}`);
  return parts.flatMap((part, i) => (part.length === 0 ? [] : linkSpans(part, i % 2 === 1, linker)));
}

function tableCells(line) {
  return line
    .trim()
    .replace(/^\|/, '')
    .replace(/\|$/, '')
    .split('|')
    .map((c) => c.trim());
}

const LIST = /^(\s*)([-*]|\d+\.)\s+(.*)$/;

/**
 * The subset of markdown the texts use: `#` title, `##` headings, paragraphs (a paragraph that is
 * all bold is a subheading), `-` and `1.` lists, `|` tables, **bold**, bare links.
 */
function parseMarkdown(markdown, selfSlug) {
  const linker = pageLinker(selfSlug);
  const lines = markdown.replace(/\r\n/g, '\n').split('\n');
  const blocks = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line.trim() === '') {
      i++;
      continue;
    }
    const heading = /^(#{1,3})\s+(.*)$/.exec(line);
    if (heading) {
      const text = heading[2].trim();
      if (heading[1].length === 1) blocks.push({ kind: 'title', text });
      else blocks.push({ kind: heading[1].length === 2 ? 'heading' : 'subheading', spans: parseInline(text, linker) });
      i++;
      continue;
    }
    if (line.trim().startsWith('|')) {
      const rows = [];
      while (i < lines.length && lines[i].trim().startsWith('|')) {
        if (!/^\s*\|?\s*:?-{3,}/.test(lines[i])) rows.push(tableCells(lines[i]).map((c) => parseInline(c, linker)));
        i++;
      }
      blocks.push({ kind: 'table', head: rows[0], rows: rows.slice(1) });
      continue;
    }
    if (LIST.test(line)) {
      const ordered = /^\s*\d+\./.test(line);
      const items = [];
      while (i < lines.length && LIST.test(lines[i])) {
        items.push(parseInline(LIST.exec(lines[i])[3].trim(), linker));
        i++;
      }
      blocks.push({ kind: 'list', ordered, items });
      continue;
    }
    const para = [];
    while (i < lines.length && lines[i].trim() !== '' && !/^#{1,3}\s/.test(lines[i]) && !lines[i].trim().startsWith('|') && !LIST.test(lines[i])) {
      para.push(lines[i].trim());
      i++;
    }
    const spans = parseInline(para.join(' '), linker);
    const allBold = spans.length > 0 && spans.every((s) => s.bold && !s.href);
    blocks.push(allBold ? { kind: 'subheading', spans: spans.map((s) => ({ text: s.text })) } : { kind: 'paragraph', spans });
  }
  return blocks;
}

/** The "**Last updated:** …" value, up to " · ". */
function lastUpdated(markdown) {
  const m = /\*\*Last updated:\*\*\s*([^\n·]*)/.exec(markdown);
  return m ? m[1].trim() : '';
}

function readLegal(root, file) {
  return fs.readFileSync(path.join(root, 'docs/legal', file), 'utf8');
}

/**
 * The texts' version, saved with each account's acceptance (step 10.1b-2): the newest "Last
 * updated" date (or "draft" while a date is still [DATE]) and the first 8 hex characters of a
 * SHA-256 of the five files, so it changes whenever a word does.
 */
function legalVersion(root) {
  const hash = crypto.createHash('sha256');
  const dates = [];
  for (const p of LEGAL_PAGES) {
    const text = readLegal(root, p.file);
    hash.update(`${p.file}\n${text}\n`);
    dates.push(lastUpdated(text));
  }
  const parsed = dates.map((d) => (d.includes('[') ? NaN : Date.parse(d)));
  const date = parsed.some((t) => Number.isNaN(t)) ? 'draft' : new Date(Math.max(...parsed)).toISOString().slice(0, 10);
  return `${date}-${hash.digest('hex').slice(0, 8)}`;
}

function renderTexts(root) {
  // One block per line: a change to the text is a change to its line.
  const pages = LEGAL_PAGES.map((p) => {
    const text = readLegal(root, p.file);
    const blocks = parseMarkdown(text, p.slug).map((b) => `      ${JSON.stringify(b)},\n`);
    return (
      `  ${p.slug}: {\n` +
      `    slug: ${JSON.stringify(p.slug)},\n` +
      `    title: ${JSON.stringify(p.title)},\n` +
      `    updated: ${JSON.stringify(lastUpdated(text))},\n` +
      `    blocks: [\n${blocks.join('')}    ],\n` +
      '  },\n'
    );
  });
  return (
    HEADER('docs/legal/*.md') +
    "import type { LegalSlug, LegalText } from './types';\n\n" +
    `export const LEGAL_VERSION = ${JSON.stringify(legalVersion(root))};\n\n` +
    `export const LEGAL_TEXTS: Record<LegalSlug, LegalText> = {\n${pages.join('')}};\n`
  );
}

// ── Open-source licences ───────────────────────────────────────────────────

/** Copyleft licences whose text is shown in full, with the source. */
const FULL_TEXT = /\b(L?GPL|AGPL|MPL|EPL|CDDL)\b/i;

/** What a package bundles, and where its source is, when package.json doesn't say all of it. */
const ABOUT = {
  'libheif-js': {
    about:
      'Opens HEIC photos on the web. It bundles libheif (LGPL-3.0), compiled to WebAssembly, loaded as its own file (libheif.wasm) and replaceable with another build of the library.',
    sources: ['https://github.com/catdad-experiments/libheif-js', 'https://github.com/strukturag/libheif'],
  },
};

/** "(MIT OR GPL-3.0-or-later)" is used under MIT: only a licence with no permissive choice counts. */
function onlyCopyleft(license) {
  const choices = license.replace(/[()]/g, '').split(/\s+OR\s+/i);
  return choices.every((c) => FULL_TEXT.test(c));
}

function licenceOf(pkg, lock) {
  const l = pkg.license ?? lock.license;
  if (typeof l === 'string') return l;
  if (l && typeof l.type === 'string') return l.type;
  if (Array.isArray(pkg.licenses)) return pkg.licenses.map((x) => x.type ?? x).join(' OR ');
  return 'UNKNOWN';
}

function repoUrl(pkg) {
  const r = typeof pkg.repository === 'string' ? pkg.repository : pkg.repository?.url;
  if (!r) return typeof pkg.homepage === 'string' ? pkg.homepage : undefined;
  if (/^[\w.-]+\/[\w.-]+$/.test(r)) return `https://github.com/${r}`;
  const gh = /^github:(.+)$/.exec(r);
  if (gh) return `https://github.com/${gh[1]}`;
  return r
    .replace(/^git\+/, '')
    .replace(/^git:\/\//, 'https://')
    .replace(/^ssh:\/\/git@/, 'https://')
    .replace(/^git@([^:]+):/, 'https://$1/')
    .replace(/\.git$/, '')
    .replace(/#.*$/, '');
}

function licenceFile(dir, re = /^(licen[cs]e|copying)([.\-_]|$)/i) {
  let names;
  try {
    names = fs.readdirSync(dir);
  } catch {
    return undefined;
  }
  const name = names.filter((n) => re.test(n)).sort()[0];
  return name ? fs.readFileSync(path.join(dir, name), 'utf8') : undefined;
}

function copyrightLine(text) {
  if (!text) return undefined;
  const line = text
    .split('\n')
    .map((l) => l.trim())
    .find((l) => /^copyright\s*(\(c\)|©|\d{4})/i.test(l) && !/free software foundation/i.test(l));
  return line ? line.replace(/\s+/g, ' ').slice(0, 160) : undefined;
}

/**
 * Every package the app depends on at run time (package-lock.json, not dev-only), with its licence,
 * source and copyright line. Platform-only binaries (esbuild, lightningcss…) are build tools, not
 * part of the app, and differ per machine: left out.
 */
function collectLicences(root) {
  const lock = JSON.parse(fs.readFileSync(path.join(root, 'package-lock.json'), 'utf8'));
  const seen = new Map();
  for (const [key, entry] of Object.entries(lock.packages ?? {})) {
    if (!key || entry.dev || entry.link) continue;
    if (entry.optional && (entry.os || entry.cpu)) continue;
    const dir = path.join(root, key);
    let pkg = {};
    try {
      pkg = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8'));
    } catch {
      // Not installed (an optional package): the lockfile's own fields.
    }
    const name = pkg.name ?? entry.name ?? key.slice(key.lastIndexOf('node_modules/') + 'node_modules/'.length);
    const version = pkg.version ?? entry.version ?? '';
    const id = `${name}@${version}`;
    if (seen.has(id)) continue;
    const text = licenceFile(dir);
    let license = licenceOf(pkg, entry);
    // No licence field: the MIT text itself says so.
    if (license === 'UNKNOWN' && text && /Permission is hereby granted, free of charge/.test(text)) license = 'MIT';
    const item = { name, version, license };
    const source = repoUrl(pkg);
    if (source) item.source = source;
    const copyright = copyrightLine(text);
    if (copyright) item.copyright = copyright;
    const notice = /^Apache/i.test(license) ? licenceFile(dir, /^notice(\.|$)/i) : undefined;
    const copyleft = onlyCopyleft(license);
    if (copyleft || notice) {
      const extra = ABOUT[name] ?? {};
      item.notice = {
        about: extra.about ?? '',
        sources: extra.sources ?? (source ? [source] : []),
        text: (copyleft ? text : notice) ?? '',
      };
    }
    seen.set(id, item);
  }
  return [...seen.values()].sort((a, b) => (a.name === b.name ? (a.version < b.version ? -1 : 1) : a.name < b.name ? -1 : 1));
}

function renderLicences(root) {
  const all = collectLicences(root);
  const packages = all.map(({ notice, ...rest }) => rest);
  const notices = all
    .filter((p) => p.notice)
    .map((p) => ({ name: p.name, version: p.version, license: p.license, ...p.notice }));
  return (
    HEADER('package-lock.json and node_modules/*/package.json') +
    "import type { LicenceNotice, OpenSourcePackage } from './types';\n\n" +
    '/** Licences whose text is shown in full (copyleft, or an Apache NOTICE file), with the source. */\n' +
    `export const LICENCE_NOTICES: readonly LicenceNotice[] = ${JSON.stringify(notices, null, 2)};\n\n` +
    '/** Every open-source package the app depends on at run time. */\n' +
    'export const OPEN_SOURCE_PACKAGES: readonly OpenSourcePackage[] = [\n' +
    packages.map((p) => `  ${JSON.stringify(p)},\n`).join('') +
    '];\n'
  );
}

// ── The launch checklist's text rules ─────────────────────────────────────

/** Square brackets that are the text itself, not a detail to fill in: Apple's settings path. */
const NOT_PLACEHOLDERS = [/Settings → \[your name\] →/];

const CATEGORIES = [
  ['Owner details (name, address, NIF, phone, website)', /^\[(YOUR FULL LEGAL NAME|POSTAL ADDRESS|TAX ID|PHONE|WEBSITE URL)\]$/],
  ['Contact emails (support, privacy)', /^\[(SUPPORT|PRIVACY) EMAIL\]$/],
  ['Dates ("Last updated")', /^\[DATE\]$/],
  ['Backup days (privacy §7, from the Supabase plan)', /^\[X\]$/],
  ['RevenueCat lines (keep only if used)', /RevenueCat/],
  ['Free plan and free trial lines (step 10.2)', /free plan|If offered|read-only/i],
];

function categoryOf(found) {
  const c = CATEGORIES.find(([, re]) => re.test(found));
  return c ? c[0] : 'Other details';
}

/** Each bracketed detail still to fill in: { file, line, text, category }. */
function placeholders(root) {
  const out = [];
  for (const file of [...LEGAL_PAGES.map((p) => p.file), ...INTERNAL_DOCS]) {
    let text;
    try {
      text = readLegal(root, file);
    } catch {
      continue;
    }
    const internal = INTERNAL_DOCS.includes(file);
    text.split('\n').forEach((raw, n) => {
      // The breach plan's message template (> lines) keeps its [date], [what happened]…
      if (internal && raw.trimStart().startsWith('>')) return;
      let line = raw;
      for (const re of NOT_PLACEHOLDERS) line = line.replace(new RegExp(re.source, 'g'), '');
      for (const m of line.matchAll(/\[[^\]\n]+\](?!\()/g)) {
        out.push({ file: `docs/legal/${file}`, line: n + 1, text: m[0], category: internal ? 'The data-breach plan’s contacts' : categoryOf(m[0]) });
      }
    });
  }
  return out;
}

/** "DRAFT" left in a published text. */
function drafts(root) {
  const out = [];
  for (const p of LEGAL_PAGES) {
    readLegal(root, p.file)
      .split('\n')
      .forEach((line, n) => {
        if (/\bDRAFT\b/.test(line)) out.push({ file: `docs/legal/${p.file}`, line: n + 1, text: line.trim() });
      });
  }
  return out;
}

function walk(dir, out = []) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const e of entries) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) {
      if (e.name !== '__tests__' && e.name !== 'node_modules') walk(full, out);
    } else if (/\.(ts|tsx)$/.test(e.name) && !/\.test\.tsx?$/.test(e.name)) out.push(full);
  }
  return out;
}

/**
 * Text a student can read that names one of `words`: string literals and JSX text in app/ and
 * src/components/ (not comments, imports or tests), app.json's strings (permission texts) and the
 * five legal texts. Transcription is ElevenLabs (BUILD-PLAN 10.1b): none may say OpenAI or Whisper.
 */
function userFacingMentions(root, words = ['OpenAI', 'Whisper']) {
  const ts = require('typescript');
  const re = new RegExp(`\\b(${words.map(escapeRegExp).join('|')})\\b`, 'i');
  const out = [];
  const files = [...walk(path.join(root, 'app')), ...walk(path.join(root, 'src/components'))];
  for (const file of files) {
    const source = fs.readFileSync(file, 'utf8');
    const sf = ts.createSourceFile(file, source, ts.ScriptTarget.Latest, true, file.endsWith('x') ? ts.ScriptKind.TSX : ts.ScriptKind.TS);
    const visit = (node) => {
      const parent = node.parent;
      const isModuleName =
        parent && (ts.isImportDeclaration(parent) || ts.isExportDeclaration(parent) || ts.isExternalModuleReference(parent) || (ts.isCallExpression(parent) && (parent.expression.kind === ts.SyntaxKind.ImportKeyword || (ts.isIdentifier(parent.expression) && parent.expression.text === 'require'))));
      if ((ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node) || ts.isTemplateHead(node) || ts.isTemplateMiddle(node) || ts.isTemplateTail(node) || ts.isJsxText(node)) && !isModuleName) {
        const text = node.text ?? node.getText(sf);
        const m = re.exec(text);
        if (m) out.push({ file: path.relative(root, file), line: sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1, text: text.trim().slice(0, 120) });
      }
      ts.forEachChild(node, visit);
    };
    visit(sf);
  }
  const strings = [];
  const collect = (v, where) => {
    if (typeof v === 'string') strings.push([where, v]);
    else if (Array.isArray(v)) v.forEach((x, i) => collect(x, `${where}[${i}]`));
    else if (v && typeof v === 'object') for (const [k, x] of Object.entries(v)) collect(x, where ? `${where}.${k}` : k);
  };
  collect(JSON.parse(fs.readFileSync(path.join(root, 'app.json'), 'utf8')), '');
  for (const [where, v] of strings) if (re.test(v)) out.push({ file: `app.json (${where})`, line: 0, text: v.slice(0, 120) });
  for (const p of LEGAL_PAGES) {
    readLegal(root, p.file)
      .split('\n')
      .forEach((line, n) => {
        if (re.test(line)) out.push({ file: `docs/legal/${p.file}`, line: n + 1, text: line.trim().slice(0, 120) });
      });
  }
  return out;
}

module.exports = {
  LEGAL_PAGES,
  INTERNAL_DOCS,
  TEXTS_OUT,
  LICENCES_OUT,
  parseMarkdown,
  lastUpdated,
  legalVersion,
  renderTexts,
  collectLicences,
  renderLicences,
  placeholders,
  drafts,
  userFacingMentions,
};
